var o=[{title:`Qué cambia la forma`,text:`En algunos levantamientos el peso colgante puede moverse alrededor de la muñeca o del antebrazo, y se equilibra de forma distinta a una mancuerna. Las sentadillas goblet, los pesos muertos y los paseos con carga usan la kettlebell de maneras bastante sencillas. Las cargadas, los arranques y otras habilidades balísticas añaden impulso y exigencias de coordinación que pueden ser demasiado para quienes empiezan.`},{title:`Empieza por lo básico`,text:`Aprende una bisagra de cadera controlada y un peso muerto sencillo antes de probar un swing, y haz sentadillas goblet, pesos muertos, remos o paseos con carga antes del trabajo balístico de alta coordinación. Elige una kettlebell lo bastante ligera para movimientos estables y repetidos, pero lo bastante pesada para suponer un reto. El género o la edad por sí solos no pueden decirte el peso inicial adecuado; importan tu fuerza, tu experiencia y el ejercicio que elijas.`},{title:`Mecánica del swing`,text:`En un swing habitual a dos manos, la kettlebell viaja desde entre las piernas hasta aproximadamente la altura del pecho, impulsada por una potente extensión de cadera y no por levantar los brazos. Mantén la columna controlada, deja que las rodillas se flexionen un poco y guía la kettlebell por el mismo arco cada vez. No conviertas el ejercicio en una sentadilla profunda con una elevación frontal.`},{title:`Seguridad y progresión`,text:`Practica cuando el suelo, tus manos y la zona que te rodea estén despejados y secos. Deja suficiente espacio delante y detrás de ti para la trayectoria de la kettlebell. Detente cuando tu agarre o tu técnica de bisagra empiecen a fallar. Pasa de los pesos muertos y las bisagras controladas a series cortas de swings solo cuando puedas hacer el movimiento con fiabilidad.`},{title:`Cómo usar TrainUp`,text:`Indica con precisión en Perfil el tamaño de tu suelo, la altura del techo y la superficie. Tu plan elige solo ejercicios que encajan con tu espacio, tu superficie, tus limitaciones y tu coordinación, lo cual importa en los movimientos de balanceo en una habitación pequeña.`}];var s=[{label:`ACE: técnica del swing con kettlebell a dos manos`,url:`https://www.acefitness.org/continuing-education/certified/january-2025/8788/the-ace-do-it-better-series-the-two-handed-kettlebell-swing/`},{label:`Biblioteca de ejercicios de ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: técnica del entrenamiento con pesas (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var t={sections:o,sources:s};export{t as default,o as sections,s as sources};